#!/usr/bin/env python3
import base64,gzip,io,json,zlib
from collections import Counter
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
BASE=ROOT/'data/shows/backyard-rockets-s1/encoded'
FILES=['scenes_e04_trip_point.json.gzb64','scenes_e05_reserve_margin.json.gzb64','scenes_e06_ground_loop.json.gzb64','scenes_e07_ablative_armor.json.gzb64','scenes_e08_sky_piercer.json.gzb64']
EDITS=json.loads(zlib.decompress(base64.b64decode('').decode()))
by_speaker=Counter(); replaced=0
for name in FILES:
    p=BASE/name
    raw=base64.b64decode(''.join(p.read_text(encoding='utf-8').split()))
    scenes=json.loads(gzip.decompress(raw).decode('utf-8'))
    for scene in scenes:
        mapping=EDITS.get(scene.get('id'),{})
        for line in scene.get('dialogueInline',[]):
            old=line.get('text')
            if old in mapping:
                line['text']=mapping[old]
                replaced+=1
                by_speaker[line.get('speaker','?')]+=1
    data=(json.dumps(scenes,indent=2,ensure_ascii=False)+'\n').encode('utf-8')
    buf=io.BytesIO()
    with gzip.GzipFile(fileobj=buf,mode='wb',compresslevel=9,mtime=0) as z:
        z.write(data)
    p.write_text(base64.b64encode(buf.getvalue()).decode('ascii'),encoding='utf-8')
if replaced!=68:
    raise SystemExit(f'Expected 68 dialogue replacements, got {replaced}')
print('Dialogue replacements:',replaced,dict(by_speaker))
